def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid separator and compare corresponding cells across it.
    c = next((j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1), None)
    if c is not None:
        left = [row[:c] for row in grid]
        right = [row[c + 1:] for row in grid]
        width = min(len(left[0]), len(right[0]))
        return [
            [3 if left[i][j] == right[i][j] else 4 for j in range(width)]
            for i in range(h)
        ]

    r = next(i for i in range(h) if len(set(grid[i])) == 1)
    top, bottom = grid[:r], grid[r + 1:]
    return [
        [3 if top[i][j] == bottom[i][j] else 7 for j in range(len(top[i]))]
        for i in range(min(len(top), len(bottom)))
    ]
